//! Byte-exact regression pin for the ICP index-canister reply. The index was upgraded to an
//! ICRC-3-style shape and the relay's candid mirrors stopped unifying — every
//! `/api/v1/transactions` decode failed (prod-wide 503s, the convert stuck-watch blind). These
//! are the EXACT reply bytes a live mainnet `get_account_transactions` query returned that day
//! (1920 bytes; public account identifiers only). Decode must stay green against them.
#![cfg(feature = "agent")]

use dpay_relay::agent_ledger::{IcpIndexAccountTransactionsResult, IcpIndexOperation};

const CAPTURED_HEX: &str = "";

#[test]
fn captured_index_reply_decodes() {
    let clean: String = CAPTURED_HEX.chars().filter(|c| c.is_ascii_hexdigit()).collect();
    let bytes: Vec<u8> = (0..clean.len())
        .step_by(2)
        .map(|i| u8::from_str_radix(&clean[i..i + 2], 16).expect("hex"))
        .collect();
    assert_eq!(bytes.first(), Some(&0x44), "DIDL magic"); // 'D'
    let result: IcpIndexAccountTransactionsResult =
        candid::decode_one(&bytes).expect("the captured ICRC-3-era reply still decodes");
    let ok = result.expect("Ok arm");
    assert!(!ok.transactions.is_empty(), "the capture carries real rows");
    assert_eq!(ok.transactions.len(), 5, "the page held 5 rows");
    let first = &ok.transactions[0];
    assert!(first.id > 0, "row ids are positive nat64s");
    match &first.transaction.operation {
        IcpIndexOperation::Transfer(t) => {
            assert!(t.from.len() == 64, "account sides are hex account-identifier text");
            assert!(t.to.len() == 64);
        }
        other => panic!("unexpected first-row operation: {other:?}"),
    }
    assert!(
        first
            .transaction
            .timestamp
            .map_or(0, |t| t.timestamp_nanos)
            > 1_700_000_000_000_000_000
    );
}
